package com.happy.cinemaremote;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.Color;import android.view.*;import android.widget.*;import android.webkit.*;import android.net.*;import android.net.nsd.*;import java.util.*;
public class MainActivity extends Activity {
 private String pendingVoice=null;private static final int VOICE_REQUEST=410;
 public final class VoiceBridge{@JavascriptInterface public void start(){runOnUiThread(()->startVoice());}}
 private void startVoice(){Intent i=new Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE,"ko-KR");i.putExtra(android.speech.RecognizerIntent.EXTRA_PROMPT,"듣고 싶은 영화나 분위기를 말해 주세요");try{startActivityForResult(i,VOICE_REQUEST);}catch(ActivityNotFoundException e){Toast.makeText(this,"음성 입력 앱이 없습니다. 키보드의 마이크를 사용해 주세요.",Toast.LENGTH_LONG).show();}}
 private void deliverVoice(){if(web!=null&&pendingVoice!=null&&web.getProgress()==100){String text=pendingVoice;pendingVoice=null;web.evaluateJavascript("window.cinemaVoiceResult&&window.cinemaVoiceResult("+org.json.JSONObject.quote(text)+")",null);}}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==VOICE_REQUEST&&result==RESULT_OK&&data!=null){ArrayList<String> words=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty()){pendingVoice=words.get(0);deliverVoice();}}}

 private LinearLayout root,devices;private TextView note;private WebView web;private NsdManager nsd;private NsdManager.DiscoveryListener discovery;private boolean resolving=false;private final ArrayDeque<NsdServiceInfo> pending=new ArrayDeque<>();private final Set<String> found=new HashSet<>();
 public void onCreate(Bundle b){super.onCreate(b);String saved=getPreferences(0).getString("last_receiver","");if(saved.startsWith("http://"))open(saved);else showSetup();}
 private TextView label(String s,int size){TextView v=new TextView(this);v.setText(s);v.setTextSize(size);v.setTextColor(0xFFF4F0E6);v.setPadding(0,16,0,12);return v;}
 private void showSetup(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(28,40,28,24);root.setBackgroundColor(0xFF101512);root.addView(label("CINEMA REMOTE",16));root.addView(label("우리 집 액자와\n음악을 연결하세요.",30));root.addView(label("1. 프레임에 Cinema Frame APK를 설치하고 실행\n2. 휴대폰과 프레임을 같은 Wi-Fi에 연결\n3. 아래에서 프레임을 선택",15));note=label("가까운 프레임을 찾고 있습니다…",14);root.addView(note);devices=new LinearLayout(this);devices.setOrientation(1);root.addView(devices);Button scan=new Button(this);scan.setText("프레임 다시 찾기");scan.setOnClickListener(v->scan());root.addView(scan);
  EditText ip=new EditText(this);ip.setTextColor(Color.WHITE);ip.setHintTextColor(0xFF9FAB9F);ip.setHint("직접 연결: 프레임에 표시된 IP 주소");ip.setSingleLine();root.addView(ip);Button manual=new Button(this);manual.setText("주소로 연결");manual.setOnClickListener(v->{String host=ip.getText().toString().trim().replace("http://","").replace(":8787","").replace("/","");if(host.matches("(?:[0-9]{1,3}\\.){3}[0-9]{1,3}"))open("http://"+host+":8787");else note.setText("프레임 화면의 IP 주소를 입력해 주세요");});root.addView(manual);setContentView(root);scan();}
 private void scan(){stopScan();found.clear();devices.removeAllViews();pending.clear();nsd=(NsdManager)getSystemService(NSD_SERVICE);discovery=new NsdManager.DiscoveryListener(){public void onDiscoveryStarted(String t){runOnUiThread(()->note.setText("같은 Wi-Fi의 프레임을 찾고 있습니다…"));}public void onServiceFound(NsdServiceInfo i){synchronized(pending){pending.add(i);}resolveNext();}public void onServiceLost(NsdServiceInfo i){}public void onDiscoveryStopped(String t){}public void onStartDiscoveryFailed(String t,int e){runOnUiThread(()->note.setText("자동 검색이 안 되면 프레임의 IP 주소로 연결해 주세요"));}public void onStopDiscoveryFailed(String t,int e){}};try{nsd.discoverServices("_cinemaframe._tcp.",NsdManager.PROTOCOL_DNS_SD,discovery);}catch(Exception e){note.setText("직접 주소로 연결해 주세요");}}
 private synchronized void resolveNext(){if(resolving)return;NsdServiceInfo next;synchronized(pending){next=pending.poll();}if(next==null)return;resolving=true;nsd.resolveService(next,new NsdManager.ResolveListener(){public void onResolveFailed(NsdServiceInfo i,int error){resolving=false;resolveNext();}public void onServiceResolved(NsdServiceInfo i){resolving=false;String host=i.getHost().getHostAddress();if(host.contains(":")){resolveNext();return;}String url="http://"+host+":"+i.getPort();runOnUiThread(()->{if(found.add(url)){Button b=new Button(MainActivity.this);b.setText(i.getServiceName()+"\n"+host);b.setOnClickListener(v->open(url));devices.addView(b);note.setText("프레임을 찾았습니다. 선택해 주세요.");}});resolveNext();}});}
 private void open(String url){stopScan();web=new WebView(this);web.setBackgroundColor(0xFF101512);web.getSettings().setJavaScriptEnabled(true);web.getSettings().setDomStorageEnabled(true);web.getSettings().setCacheMode(WebSettings.LOAD_NO_CACHE);web.getSettings().setAllowFileAccess(false);web.getSettings().setAllowContentAccess(false);web.addJavascriptInterface(new VoiceBridge(),"CinemaVoice");web.setWebViewClient(new WebViewClient(){public void onPageFinished(WebView v,String pageUrl){deliverVoice();}public void onReceivedError(WebView v,WebResourceRequest r,WebResourceError e){if(r.isForMainFrame()){v.post(()->{if(web!=v)return;web=null;v.destroy();showSetup();note.setText("저장된 프레임에 연결하지 못했습니다. Wi-Fi와 프레임 전원을 확인하고 다시 선택해 주세요.");});}}public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){Uri u=r.getUrl();if(u.getHost()!=null&&(u.getHost().equals("spotify.com")||u.getHost().endsWith(".spotify.com"))){startActivity(new Intent(Intent.ACTION_VIEW,u));return true;}Uri receiver=Uri.parse(url);if(!java.util.Objects.equals(receiver.getHost(),u.getHost())||receiver.getPort()!=u.getPort()){if("http".equals(u.getScheme())||"https".equals(u.getScheme()))startActivity(new Intent(Intent.ACTION_VIEW,u));return true;}return false;}});setContentView(web);web.loadUrl(url);getPreferences(0).edit().putString("last_receiver",url).apply();}
 private void stopScan(){if(nsd!=null&&discovery!=null)try{nsd.stopServiceDiscovery(discovery);}catch(Exception ignored){}discovery=null;}
 public void onBackPressed(){if(web!=null){web.destroy();web=null;showSetup();}else super.onBackPressed();}public void onDestroy(){stopScan();if(web!=null)web.destroy();super.onDestroy();}
}
